cat > /app/output/styles.css <<'EOF'
:root {
  --ink: #07050b;
  --muted: #655f72;
  --paper: #fffaf5;
  --surface: #ffffff;
  --soft: #f7f0ff;
  --purple: #7638fa;
  --purple-dark: #4b16c9;
  --orange: #ff7a00;
  --pink: #ff3ea5;
  --lemon: #fff06b;
  --mint: #dffced;
  --line: rgba(7, 5, 11, 0.12);
  --shadow: 0 24px 80px rgba(50, 25, 105, 0.16);
  --radius-xl: 42px;
  --radius-lg: 28px;
  --radius-md: 18px;
}

* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  color: var(--ink);
  background:
    radial-gradient(circle at top left, rgba(118, 56, 250, 0.18), transparent 34rem),
    radial-gradient(circle at 85% 10%, rgba(255, 122, 0, 0.16), transparent 28rem),
    linear-gradient(180deg, #fffaf5 0%, #ffffff 46%, #fff7ee 100%);
  font-family: "Plus Jakarta Sans", sans-serif;
  overflow-x: hidden;
}

body.menu-open {
  overflow: hidden;
}

a {
  color: inherit;
  text-decoration: none;
}

button,
select {
  font: inherit;
}

.page-shell {
  min-height: 100vh;
}

.site-header {
  position: sticky;
  top: 0;
  z-index: 40;
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: min(1180px, calc(100% - 32px));
  margin: 16px auto 0;
  padding: 13px 14px 13px 18px;
  border: 1px solid rgba(255, 255, 255, 0.7);
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.78);
  box-shadow: 0 12px 36px rgba(34, 16, 68, 0.11);
  backdrop-filter: blur(18px);
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-family: "Space Grotesk", sans-serif;
  font-size: 1.08rem;
  font-weight: 700;
  letter-spacing: -0.04em;
}

.brand-mark {
  width: 34px;
  height: 34px;
  border-radius: 12px;
  background:
    radial-gradient(circle at 65% 30%, #fff 0 10%, transparent 11%),
    conic-gradient(from 215deg, var(--orange), var(--pink), var(--purple), var(--orange));
  box-shadow: 0 8px 22px rgba(118, 56, 250, 0.34);
}

.desktop-nav {
  display: flex;
  gap: 6px;
  padding: 4px;
  border-radius: 999px;
  background: rgba(7, 5, 11, 0.045);
}

.desktop-nav a,
.login-link {
  border-radius: 999px;
  padding: 10px 16px;
  font-size: 0.9rem;
  font-weight: 800;
  transition: background 180ms ease, color 180ms ease, transform 180ms ease;
}

.desktop-nav a:hover {
  background: var(--surface);
  transform: translateY(-1px);
}

.login-link {
  display: inline-flex;
  background: var(--ink);
  color: #fff;
}

.login-link:hover,
.mobile-login:hover {
  background: var(--purple);
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 8px;
}

.hamburger {
  display: none;
  width: 46px;
  height: 46px;
  border: 0;
  border-radius: 999px;
  background: var(--ink);
  cursor: pointer;
  place-items: center;
}

.hamburger span {
  display: block;
  width: 18px;
  height: 2px;
  margin: 3px 0;
  border-radius: 999px;
  background: #fff;
  transition: transform 220ms ease, opacity 220ms ease;
}

.hamburger[aria-expanded="true"] span:nth-child(1) {
  transform: translateY(5px) rotate(45deg);
}

.hamburger[aria-expanded="true"] span:nth-child(2) {
  opacity: 0;
}

.hamburger[aria-expanded="true"] span:nth-child(3) {
  transform: translateY(-5px) rotate(-45deg);
}

.mobile-menu {
  position: fixed;
  inset: 84px 16px auto;
  z-index: 35;
  padding: 18px;
  border-radius: 30px;
  background: rgba(255, 255, 255, 0.96);
  box-shadow: var(--shadow);
  backdrop-filter: blur(18px);
  transform-origin: top;
  animation: menuDrop 220ms ease both;
}

.mobile-menu nav {
  display: grid;
  gap: 8px;
}

.mobile-menu a {
  display: flex;
  justify-content: space-between;
  padding: 15px 16px;
  border-radius: 18px;
  background: #f7f3ff;
  font-weight: 800;
}

.mobile-login {
  justify-content: center !important;
  margin-top: 10px;
  background: var(--ink) !important;
  color: #fff;
}

.hero {
  display: grid;
  grid-template-columns: minmax(0, 1.04fr) minmax(340px, 0.96fr);
  align-items: center;
  gap: 42px;
  width: min(1180px, calc(100% - 32px));
  min-height: calc(100vh - 96px);
  margin: 0 auto;
  padding: 72px 0 88px;
}

.eyebrow {
  display: inline-flex;
  width: fit-content;
  margin: 0 0 18px;
  padding: 8px 13px;
  border: 1px solid rgba(255, 255, 255, 0.42);
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.22);
  color: #fff;
  font-size: 0.76rem;
  font-weight: 900;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.eyebrow.dark {
  border-color: rgba(118, 56, 250, 0.18);
  background: #f0e8ff;
  color: var(--purple-dark);
}

.hero-copy .eyebrow {
  background: #fff;
  color: var(--purple-dark);
  box-shadow: 0 10px 30px rgba(118, 56, 250, 0.12);
}

h1,
h2,
h3 {
  font-family: "Space Grotesk", sans-serif;
  letter-spacing: -0.065em;
  line-height: 0.95;
}

h1 {
  max-width: 790px;
  margin: 0;
  font-size: clamp(4rem, 8.6vw, 8.9rem);
}

.hero-subtitle {
  max-width: 650px;
  margin: 28px 0 0;
  color: var(--muted);
  font-size: clamp(1.05rem, 2vw, 1.35rem);
  line-height: 1.6;
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 14px;
  margin-top: 36px;
}

.button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 56px;
  padding: 0 24px;
  border-radius: 999px;
  font-weight: 900;
  transition: transform 190ms ease, box-shadow 190ms ease, background 190ms ease;
}

.button:hover {
  transform: translateY(-3px);
}

.button-primary {
  background: var(--ink);
  color: #fff;
  box-shadow: 0 18px 42px rgba(7, 5, 11, 0.2);
}

.button-primary:hover {
  background: linear-gradient(135deg, var(--purple), var(--pink), var(--orange));
}

.button-secondary {
  border: 1px solid var(--line);
  background: #fff;
}

.button-light {
  background: #fff;
  color: var(--ink);
}

.hero-art {
  position: relative;
  min-height: 620px;
  border-radius: var(--radius-xl);
  background:
    radial-gradient(circle at 35% 15%, rgba(255, 240, 107, 0.9), transparent 12rem),
    radial-gradient(circle at 70% 70%, rgba(255, 62, 165, 0.55), transparent 13rem),
    linear-gradient(140deg, var(--purple) 0%, #b531ff 48%, var(--orange) 100%);
  box-shadow: var(--shadow);
  overflow: hidden;
}

.hero-art::before {
  content: "";
  position: absolute;
  inset: 24px;
  border: 1px solid rgba(255, 255, 255, 0.28);
  border-radius: 34px;
}

.orbit {
  position: absolute;
  border: 1px solid rgba(255, 255, 255, 0.44);
  border-radius: 999px;
  animation: float 7s ease-in-out infinite;
}

.orbit-one {
  width: 250px;
  height: 250px;
  top: 28px;
  right: -58px;
}

.orbit-two {
  width: 190px;
  height: 190px;
  bottom: 40px;
  left: -54px;
  animation-delay: -2s;
}

.phone-card {
  position: absolute;
  top: 64px;
  left: 50%;
  width: min(310px, 68%);
  padding: 18px;
  border: 10px solid #141017;
  border-radius: 44px;
  background: #fff;
  box-shadow: 0 32px 80px rgba(0, 0, 0, 0.34);
  transform: translateX(-50%) rotate(-5deg);
}

.phone-topbar,
.reaction-row {
  display: flex;
  gap: 8px;
  align-items: center;
}

.phone-topbar span:first-child {
  width: 68px;
  height: 10px;
  border-radius: 999px;
  background: #141017;
}

.phone-topbar span:last-child {
  width: 26px;
  height: 10px;
  border-radius: 999px;
  background: #ddd3e7;
}

.story-row {
  display: flex;
  gap: 10px;
  margin: 18px 0;
}

.story-row span {
  width: 48px;
  height: 48px;
  border: 3px solid #fff;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--orange), var(--pink), var(--purple));
  box-shadow: 0 0 0 2px var(--pink);
}

.feed-image {
  height: 285px;
  border-radius: 28px;
  background:
    radial-gradient(circle at 70% 25%, #fff06b 0 11%, transparent 12%),
    linear-gradient(135deg, #17101f 0%, #6f30f5 45%, #ff7a00 100%);
}

.reaction-row {
  margin: 16px 0 12px;
}

.reaction-row span {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: #f1eafd;
}

.caption-line {
  width: 58%;
  height: 10px;
  margin-top: 8px;
  border-radius: 999px;
  background: #ede6f7;
}

.caption-line.wide {
  width: 86%;
}

.floating-card {
  position: absolute;
  display: grid;
  gap: 4px;
  padding: 16px 18px;
  border: 1px solid rgba(255, 255, 255, 0.42);
  border-radius: 22px;
  background: rgba(255, 255, 255, 0.78);
  box-shadow: 0 18px 42px rgba(0, 0, 0, 0.16);
  backdrop-filter: blur(16px);
}

.floating-card strong {
  font-family: "Space Grotesk", sans-serif;
  font-size: 1.75rem;
